package cn.lims.inventory;

import cn.lims.audit.AuditService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1/inventory")
public class InventoryController {
    private final JdbcTemplate jdbc; private final AuditService audit;
    public InventoryController(JdbcTemplate jdbc,AuditService audit){this.jdbc=jdbc;this.audit=audit;}

    @GetMapping("/materials") @PreAuthorize("hasAuthority('inventory:stock:view')")
    public List<Material> materials(){return jdbc.query("select m.id,m.code,m.name,m.category,m.specification,m.base_unit,m.hazard_type,m.min_stock,m.status,m.version,exists(select 1 from inv_stock_batch b where b.material_id=m.id),exists(select 1 from inv_purchase_request p where p.material_id=m.id and p.deleted=false) from inv_material m where m.deleted=false order by m.code",(r,n)->{boolean inStockLibrary=r.getBoolean(11);boolean inPurchaseRequest=r.getBoolean(12);boolean deletable=!inStockLibrary&&!inPurchaseRequest;String reason=inStockLibrary&&inPurchaseRequest?"该物料已存在于物料信息库和采购申请中，不能删除":inStockLibrary?"该物料已存在于物料信息库中，不能删除":inPurchaseRequest?"该物料已存在于采购申请中，不能删除":null;return new Material(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getBigDecimal(8),r.getString(9),r.getInt(10),deletable,reason);});}
    @PostMapping("/materials") @Transactional @PreAuthorize("hasAuthority('inventory:material:manage')")
    public Id createMaterial(@Valid @RequestBody MaterialRequest q,Authentication a){Long id=jdbc.queryForObject("insert into inv_material(code,name,category,specification,base_unit,hazard_type,min_stock,status) values(?,?,?,?,?,?,?,?) returning id",Long.class,q.code(),q.name(),q.category(),q.specification(),q.baseUnit(),q.hazardType(),q.minStock(),q.status());audit.record(a,"inventory:material:create","MATERIAL",id,null,q.toString());return new Id(id);}
    @PutMapping("/materials/{id}") @Transactional @PreAuthorize("hasAuthority('inventory:material:manage')")
    public void updateMaterial(@PathVariable long id,@Valid @RequestBody MaterialRequest q,Authentication a){if(jdbc.update("update inv_material set code=?,name=?,category=?,specification=?,base_unit=?,hazard_type=?,min_stock=?,status=?,updated_at=current_timestamp,version=version+1 where id=? and deleted=false and version=?",q.code(),q.name(),q.category(),q.specification(),q.baseUnit(),q.hazardType(),q.minStock(),q.status(),id,q.version())==0)throw new IllegalArgumentException("物料不存在或已被修改");audit.record(a,"inventory:material:update","MATERIAL",id,null,q.toString());}
    @DeleteMapping("/materials/{id}") @Transactional @PreAuthorize("hasAuthority('inventory:material:manage')")
    public void deleteMaterial(@PathVariable long id,Authentication a){Boolean inStockLibrary=jdbc.queryForObject("select exists(select 1 from inv_stock_batch where material_id=?)",Boolean.class,id);Boolean inPurchaseRequest=jdbc.queryForObject("select exists(select 1 from inv_purchase_request where material_id=? and deleted=false)",Boolean.class,id);if(Boolean.TRUE.equals(inStockLibrary)&&Boolean.TRUE.equals(inPurchaseRequest))throw new IllegalArgumentException("该物料已存在于物料信息库和采购申请中，不能删除");if(Boolean.TRUE.equals(inStockLibrary))throw new IllegalArgumentException("该物料已存在于物料信息库中，不能删除");if(Boolean.TRUE.equals(inPurchaseRequest))throw new IllegalArgumentException("该物料已存在于采购申请中，不能删除");if(jdbc.update("update inv_material set deleted=true,status='DISABLED' where id=? and deleted=false",id)==0)throw new IllegalArgumentException("物料不存在");audit.record(a,"inventory:material:delete","MATERIAL",id,null,"deleted");}

    @GetMapping("/suppliers") @PreAuthorize("hasAuthority('inventory:stock:view')")
    public List<Supplier> suppliers(){return jdbc.query("select id,code,name,contact_name,contact_phone,qualification_expiry,status,version from inv_supplier where deleted=false order by code",(r,n)->new Supplier(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getObject(6,LocalDate.class),r.getString(7),r.getInt(8)));}
    @PostMapping("/suppliers") @Transactional @PreAuthorize("hasAuthority('inventory:supplier:manage')")
    public Id createSupplier(@Valid @RequestBody SupplierRequest q,Authentication a){Long id=jdbc.queryForObject("insert into inv_supplier(code,name,contact_name,contact_phone,qualification_expiry,status) values(?,?,?,?,?,?) returning id",Long.class,q.code(),q.name(),q.contactName(),q.contactPhone(),q.qualificationExpiry(),q.status());audit.record(a,"inventory:supplier:create","SUPPLIER",id,null,q.toString());return new Id(id);}
    @PutMapping("/suppliers/{id}") @Transactional @PreAuthorize("hasAuthority('inventory:supplier:manage')")
    public void updateSupplier(@PathVariable long id,@Valid @RequestBody SupplierRequest q,Authentication a){if(jdbc.update("update inv_supplier set code=?,name=?,contact_name=?,contact_phone=?,qualification_expiry=?,status=?,updated_at=current_timestamp,version=version+1 where id=? and deleted=false and version=?",q.code(),q.name(),q.contactName(),q.contactPhone(),q.qualificationExpiry(),q.status(),id,q.version())==0)throw new IllegalArgumentException("供应商不存在或已被修改");audit.record(a,"inventory:supplier:update","SUPPLIER",id,null,q.toString());}

    @GetMapping("/purchase-requests") @PreAuthorize("hasAuthority('inventory:stock:view')")
    public List<Purchase> purchases(){return jdbc.query("select p.id,p.request_no,p.material_id,m.code,m.name,p.quantity,p.expected_date,p.purpose,p.status,p.review_comment,p.created_at,p.version,p.receipt_supplier_id,p.receipt_batch_no,p.receipt_warehouse,p.receipt_location,p.receipt_quantity,p.receipt_unit_cost,p.receipt_production_date,p.receipt_expiry_date,p.receipt_purpose,p.receipt_review_comment from inv_purchase_request p join inv_material m on m.id=p.material_id where p.deleted=false order by p.id desc",(r,n)->new Purchase(r.getLong(1),r.getString(2),r.getLong(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getObject(7,LocalDate.class),r.getString(8),r.getString(9),r.getString(10),r.getObject(11,LocalDateTime.class),r.getInt(12),r.getObject(13,Long.class),r.getString(14),r.getString(15),r.getString(16),r.getBigDecimal(17),r.getBigDecimal(18),r.getObject(19,LocalDate.class),r.getObject(20,LocalDate.class),r.getString(21),r.getString(22)));}
    @PostMapping("/purchase-requests") @Transactional @PreAuthorize("hasAuthority('inventory:purchase:manage')")
    public Id createPurchase(@Valid @RequestBody PurchaseRequest q,Authentication a){Long uid=userId(a);Long dept=jdbc.queryForObject("select dept_id from sys_user where id=?",Long.class,uid);String no="CG"+System.currentTimeMillis();Long id=jdbc.queryForObject("insert into inv_purchase_request(request_no,material_id,quantity,expected_date,purpose,applicant_id,dept_id) values(?,?,?,?,?,?,?) returning id",Long.class,no,q.materialId(),q.quantity(),q.expectedDate(),q.purpose(),uid,dept);audit.record(a,"inventory:purchase:create","PURCHASE",id,null,no);return new Id(id);}
    @PostMapping("/purchase-requests/{id}/submit") @Transactional @PreAuthorize("hasAuthority('inventory:purchase:manage')")
    public void submitPurchase(@PathVariable long id,Authentication a){transition(id,"DRAFT","SUBMITTED",null,a,"submit");}
    @DeleteMapping("/purchase-requests/{id}") @Transactional @PreAuthorize("hasAuthority('inventory:purchase:manage')")
    public void deletePurchase(@PathVariable long id,Authentication a){if(jdbc.update("update inv_purchase_request set deleted=true,updated_at=current_timestamp where id=? and status='DRAFT' and deleted=false",id)==0)throw new IllegalArgumentException("仅草稿状态的采购申请可以删除");audit.record(a,"inventory:purchase:delete","PURCHASE",id,"DRAFT","deleted");}
    @PostMapping("/purchase-requests/{id}/review") @Transactional @PreAuthorize("hasAuthority('inventory:purchase:review')")
    public void reviewPurchase(@PathVariable long id,@Valid @RequestBody Review q,Authentication a){String target=q.approved()?"APPROVED":"DRAFT";if(jdbc.update("update inv_purchase_request set status=?,review_comment=?,reviewed_by=?,reviewed_at=current_timestamp,updated_at=current_timestamp where id=? and status='SUBMITTED'",target,q.comment(),userId(a),id)==0)throw new IllegalArgumentException("仅待审批状态的采购申请可以审批或退回");audit.record(a,"inventory:purchase:review","PURCHASE",id,"SUBMITTED",target);}

    @PostMapping("/purchase-requests/{id}/receipt-submit") @Transactional @PreAuthorize("hasAuthority('inventory:stock:manage')")
    public void submitPurchaseReceipt(@PathVariable long id,@Valid @RequestBody PurchaseReceipt q,Authentication a){if(jdbc.update("update inv_purchase_request set status='RECEIPT_REVIEW',receipt_supplier_id=?,receipt_batch_no=?,receipt_warehouse=?,receipt_location=?,receipt_quantity=?,receipt_unit_cost=?,receipt_production_date=?,receipt_expiry_date=?,receipt_purpose=?,receipt_submitted_by=?,receipt_submitted_at=current_timestamp,receipt_review_comment=null,updated_at=current_timestamp,version=version+1 where id=? and status='APPROVED' and deleted=false",q.supplierId(),q.batchNo(),q.warehouse(),q.location(),q.quantity(),q.unitCost(),q.productionDate(),q.expiryDate(),q.purpose(),userId(a),id)==0)throw new IllegalArgumentException("仅已通过的采购申请可以提交验收入库审核");audit.record(a,"inventory:purchase:receipt-submit","PURCHASE",id,"APPROVED","RECEIPT_REVIEW");}

    @PostMapping("/purchase-requests/{id}/receipt-review") @Transactional @PreAuthorize("hasAuthority('inventory:purchase:review')")
    public void reviewPurchaseReceipt(@PathVariable long id,@Valid @RequestBody Review q,Authentication a){var rows=jdbc.queryForList("select material_id,request_no,receipt_supplier_id,receipt_batch_no,receipt_warehouse,receipt_location,receipt_quantity,receipt_unit_cost,receipt_production_date,receipt_expiry_date,receipt_purpose from inv_purchase_request where id=? and status='RECEIPT_REVIEW' and deleted=false for update",id);if(rows.isEmpty())throw new IllegalArgumentException("仅待入库审核的采购申请可以审核");if(!q.approved()){jdbc.update("update inv_purchase_request set status='APPROVED',receipt_review_comment=?,receipt_reviewed_by=?,receipt_reviewed_at=current_timestamp,updated_at=current_timestamp,version=version+1 where id=?",q.comment(),userId(a),id);audit.record(a,"inventory:purchase:receipt-return","PURCHASE",id,"RECEIPT_REVIEW","APPROVED");return;}var p=rows.get(0);Receipt receipt=new Receipt(((Number)p.get("material_id")).longValue(),p.get("receipt_supplier_id")==null?null:((Number)p.get("receipt_supplier_id")).longValue(),(String)p.get("receipt_batch_no"),(String)p.get("receipt_warehouse"),(String)p.get("receipt_location"),(BigDecimal)p.get("receipt_quantity"),(BigDecimal)p.get("receipt_unit_cost"),dateValue(p.get("receipt_production_date")),dateValue(p.get("receipt_expiry_date")),(String)p.get("request_no"),(String)p.get("receipt_purpose"));postReceipt(receipt,a);jdbc.update("update inv_purchase_request set status='RECEIVED',receipt_review_comment=?,receipt_reviewed_by=?,receipt_reviewed_at=current_timestamp,updated_at=current_timestamp,version=version+1 where id=?",q.comment(),userId(a),id);audit.record(a,"inventory:purchase:receipt-approve","PURCHASE",id,"RECEIPT_REVIEW","RECEIVED");}

    @PostMapping("/receipts") @Transactional @PreAuthorize("hasAuthority('inventory:stock:manage')")
    public Id receipt(@Valid @RequestBody Receipt q,Authentication a){return postReceipt(q,a);}

    @GetMapping("/issue-requests") @PreAuthorize("hasAuthority('inventory:stock:view')")
    public List<IssueRequestView> issues(){return jdbc.query("select i.id,i.request_no,i.batch_id,m.code,m.name,b.batch_no,b.warehouse,b.location,i.quantity,m.base_unit,i.purpose,i.status,i.review_comment,i.created_at,i.version from inv_issue_request i join inv_stock_batch b on b.id=i.batch_id join inv_material m on m.id=b.material_id where i.deleted=false order by i.id desc",(r,n)->new IssueRequestView(r.getLong(1),r.getString(2),r.getLong(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getBigDecimal(9),r.getString(10),r.getString(11),r.getString(12),r.getString(13),r.getObject(14,LocalDateTime.class),r.getInt(15)));}
    @PostMapping("/issue-requests") @Transactional @PreAuthorize("hasAuthority('inventory:stock:manage')")
    public Id createIssue(@Valid @RequestBody Issue q,Authentication a){BigDecimal qty=jdbc.queryForObject("select quantity from inv_stock_batch where id=?",BigDecimal.class,q.batchId());if(qty.compareTo(q.quantity())<0)throw new IllegalArgumentException("申请数量不能超过当前库存");String no="CKSQ"+System.currentTimeMillis();Long id=jdbc.queryForObject("insert into inv_issue_request(request_no,batch_id,quantity,purpose,applicant_id) values(?,?,?,?,?) returning id",Long.class,no,q.batchId(),q.quantity(),q.purpose(),userId(a));audit.record(a,"inventory:issue:create","ISSUE_REQUEST",id,null,no);return new Id(id);}
    @PostMapping("/issue-requests/{id}/submit") @Transactional @PreAuthorize("hasAuthority('inventory:stock:manage')")
    public void submitIssue(@PathVariable long id,Authentication a){if(jdbc.update("update inv_issue_request set status='SUBMITTED',updated_at=current_timestamp,version=version+1 where id=? and status='DRAFT' and deleted=false",id)==0)throw new IllegalArgumentException("仅草稿状态的出库申请可以提交");audit.record(a,"inventory:issue:submit","ISSUE_REQUEST",id,"DRAFT","SUBMITTED");}
    @DeleteMapping("/issue-requests/{id}") @Transactional @PreAuthorize("hasAuthority('inventory:stock:manage')")
    public void deleteIssue(@PathVariable long id,Authentication a){if(jdbc.update("update inv_issue_request set deleted=true,updated_at=current_timestamp where id=? and status='DRAFT' and deleted=false",id)==0)throw new IllegalArgumentException("仅草稿状态的出库申请可以删除");audit.record(a,"inventory:issue:delete","ISSUE_REQUEST",id,"DRAFT","deleted");}
    @PostMapping("/issue-requests/{id}/review") @Transactional @PreAuthorize("hasAuthority('inventory:purchase:review')")
    public void reviewIssue(@PathVariable long id,@Valid @RequestBody Review q,Authentication a){var rows=jdbc.queryForList("select request_no,batch_id,quantity,purpose from inv_issue_request where id=? and status='SUBMITTED' and deleted=false for update",id);if(rows.isEmpty())throw new IllegalArgumentException("仅待审核状态的出库申请可以审核");if(!q.approved()){jdbc.update("update inv_issue_request set status='DRAFT',review_comment=?,reviewed_by=?,reviewed_at=current_timestamp,updated_at=current_timestamp,version=version+1 where id=?",q.comment(),userId(a),id);audit.record(a,"inventory:issue:return","ISSUE_REQUEST",id,"SUBMITTED","DRAFT");return;}var request=rows.get(0);long batchId=((Number)request.get("batch_id")).longValue();BigDecimal quantity=(BigDecimal)request.get("quantity");var batches=jdbc.queryForList("select material_id,quantity,unit_cost from inv_stock_batch where id=? for update",batchId);if(batches.isEmpty())throw new IllegalArgumentException("库存批次不存在");var batch=batches.get(0);BigDecimal stockQuantity=(BigDecimal)batch.get("quantity");if(stockQuantity.compareTo(BigDecimal.ZERO)<=0)throw new IllegalArgumentException("库存已经没有，不能再出库");if(stockQuantity.compareTo(quantity)<0)throw new IllegalArgumentException("库存不足，不能通过出库申请");jdbc.update("update inv_stock_batch set quantity=quantity-?,version=version+1 where id=?",quantity,batchId);String txnNo="CK"+System.currentTimeMillis();Long txnId=jdbc.queryForObject("insert into inv_stock_txn(txn_no,biz_type,biz_no,material_id,batch_id,direction,quantity,unit_cost,purpose,operator_id) values(?,'ISSUE',?,?,?,'OUT',?,?,?,?) returning id",Long.class,txnNo,request.get("request_no"),batch.get("material_id"),batchId,quantity,batch.get("unit_cost"),request.get("purpose"),userId(a));jdbc.update("update inv_issue_request set status='ISSUED',review_comment=?,reviewed_by=?,reviewed_at=current_timestamp,stock_txn_id=?,updated_at=current_timestamp,version=version+1 where id=?",q.comment(),userId(a),txnId,id);audit.record(a,"inventory:issue:approve","ISSUE_REQUEST",id,"SUBMITTED","ISSUED");}

    @GetMapping("/stocks") @PreAuthorize("hasAuthority('inventory:stock:view')")
    public List<Stock> stocks(){return jdbc.query("select b.id,m.code,m.name,m.category,m.base_unit,m.min_stock,b.batch_no,b.warehouse,b.location,b.quantity,b.unit_cost,b.expiry_date,case when b.quantity=0 then 'OUT_OF_STOCK' when b.quantity<=m.min_stock then 'LOW' when b.expiry_date<current_date then 'EXPIRED' when b.expiry_date<=current_date+30 then 'EXPIRING' else 'NORMAL' end from inv_stock_batch b join inv_material m on m.id=b.material_id and m.deleted=false order by m.code,b.expiry_date",(r,n)->new Stock(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getString(7),r.getString(8),r.getString(9),r.getBigDecimal(10),r.getBigDecimal(11),r.getObject(12,LocalDate.class),r.getString(13)));}
    @GetMapping("/stock-transactions") @PreAuthorize("hasAuthority('inventory:stock:view')")
    public List<Txn> txns(){return jdbc.query("select t.id,t.txn_no,t.biz_type,t.biz_no,m.name,b.batch_no,t.direction,t.quantity,t.unit_cost,t.purpose,t.occurred_at from inv_stock_txn t join inv_material m on m.id=t.material_id join inv_stock_batch b on b.id=t.batch_id order by t.id desc",(r,n)->new Txn(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getString(10),r.getObject(11,LocalDateTime.class)));}
    @GetMapping("/alerts") @PreAuthorize("hasAuthority('inventory:stock:view')") public List<Stock> alerts(){return stocks().stream().filter(s->!"NORMAL".equals(s.alertStatus())).toList();}
    @GetMapping("/summary") @PreAuthorize("hasAuthority('inventory:stock:view')") public Summary summary(){return jdbc.queryForObject("select count(distinct material_id),coalesce(sum(quantity*unit_cost),0),count(*) filter(where quantity<=m.min_stock),count(*) filter(where expiry_date<=current_date+30) from inv_stock_batch b join inv_material m on m.id=b.material_id where m.deleted=false",(r,n)->new Summary(r.getLong(1),r.getBigDecimal(2),r.getLong(3),r.getLong(4)));}

    private void transition(long id,String from,String to,String comment,Authentication a,String action){if(jdbc.update("update inv_purchase_request set status=?,review_comment=coalesce(?,review_comment),updated_at=current_timestamp where id=? and status=?",to,comment,id,from)==0)throw new IllegalArgumentException("采购申请状态不允许此操作");audit.record(a,"inventory:purchase:"+action,"PURCHASE",id,from,to);}
    private Id postReceipt(Receipt q,Authentication a){Long batch=jdbc.query("select id from inv_stock_batch where material_id=? and batch_no=? and warehouse=? and coalesce(location,'')=coalesce(?,'')",(r,n)->r.getLong(1),q.materialId(),q.batchNo(),q.warehouse(),q.location()).stream().findFirst().orElse(null);if(batch==null)batch=jdbc.queryForObject("insert into inv_stock_batch(material_id,supplier_id,batch_no,warehouse,location,quantity,unit_cost,production_date,expiry_date) values(?,?,?,?,?,?,?,?,?) returning id",Long.class,q.materialId(),q.supplierId(),q.batchNo(),q.warehouse(),q.location(),q.quantity(),q.unitCost(),q.productionDate(),q.expiryDate());else jdbc.update("update inv_stock_batch set quantity=quantity+?,unit_cost=((quantity*unit_cost)+(?*?))/(quantity+?),version=version+1 where id=?",q.quantity(),q.quantity(),q.unitCost(),q.quantity(),batch);String no="RK"+System.currentTimeMillis();Long tid=jdbc.queryForObject("insert into inv_stock_txn(txn_no,biz_type,biz_no,material_id,batch_id,direction,quantity,unit_cost,purpose,operator_id) values(?,'RECEIPT',?,?,?,'IN',?,?,?,?) returning id",Long.class,no,q.bizNo(),q.materialId(),batch,q.quantity(),q.unitCost(),q.purpose(),userId(a));audit.record(a,"inventory:receipt:post","STOCK_TXN",tid,null,no);return new Id(tid);}
    private LocalDate dateValue(Object value){if(value==null)return null;if(value instanceof LocalDate d)return d;if(value instanceof java.sql.Date d)return d.toLocalDate();throw new IllegalArgumentException("日期数据格式错误");}
    private Long userId(Authentication a){return jdbc.queryForObject("select id from sys_user where username=? and deleted=false",Long.class,a.getName());}
    public record Id(Long id){}
    public record Material(long id,String code,String name,String category,String specification,String baseUnit,String hazardType,BigDecimal minStock,String status,int version,boolean deletable,String deleteDisabledReason){}
    public record MaterialRequest(@NotBlank String code,@NotBlank String name,@NotBlank String category,String specification,@NotBlank String baseUnit,@NotBlank String hazardType,@NotNull BigDecimal minStock,@NotBlank String status,int version){}
    public record Supplier(long id,String code,String name,String contactName,String contactPhone,LocalDate qualificationExpiry,String status,int version){}
    public record SupplierRequest(@NotBlank String code,@NotBlank String name,String contactName,String contactPhone,LocalDate qualificationExpiry,@NotBlank String status,int version){}
    public record Purchase(long id,String requestNo,long materialId,String materialCode,String materialName,BigDecimal quantity,LocalDate expectedDate,String purpose,String status,String reviewComment,LocalDateTime createdAt,int version,Long receiptSupplierId,String receiptBatchNo,String receiptWarehouse,String receiptLocation,BigDecimal receiptQuantity,BigDecimal receiptUnitCost,LocalDate receiptProductionDate,LocalDate receiptExpiryDate,String receiptPurpose,String receiptReviewComment){}
    public record PurchaseRequest(@NotNull Long materialId,@NotNull @Positive BigDecimal quantity,LocalDate expectedDate,String purpose){}
    public record Review(boolean approved,String comment){}
    public record Receipt(@NotNull Long materialId,Long supplierId,@NotBlank String batchNo,@NotBlank String warehouse,String location,@NotNull @Positive BigDecimal quantity,@NotNull BigDecimal unitCost,LocalDate productionDate,LocalDate expiryDate,String bizNo,String purpose){}
    public record PurchaseReceipt(Long supplierId,@NotBlank String batchNo,@NotBlank String warehouse,String location,@NotNull @Positive BigDecimal quantity,@NotNull @PositiveOrZero BigDecimal unitCost,LocalDate productionDate,LocalDate expiryDate,String purpose){}
    public record Issue(@NotNull Long batchId,@NotNull @Positive BigDecimal quantity,String bizNo,@NotBlank String purpose){}
    public record IssueRequestView(long id,String requestNo,long batchId,String materialCode,String materialName,String batchNo,String warehouse,String location,BigDecimal quantity,String unit,String purpose,String status,String reviewComment,LocalDateTime createdAt,int version){}
    public record Stock(long batchId,String materialCode,String materialName,String category,String unit,BigDecimal minStock,String batchNo,String warehouse,String location,BigDecimal quantity,BigDecimal unitCost,LocalDate expiryDate,String alertStatus){}
    public record Txn(long id,String txnNo,String bizType,String bizNo,String materialName,String batchNo,String direction,BigDecimal quantity,BigDecimal unitCost,String purpose,LocalDateTime occurredAt){}
    public record Summary(long materialCount,BigDecimal stockValue,long lowStockCount,long expiryAlertCount){}
}
